#!/usr/bin/env python3
"""Independent anonymous panel delivery; all preceding panel members must close."""
import argparse,time
from pathlib import Path
import experiment as ex
R=Path(__file__).resolve().parent
p=argparse.ArgumentParser();p.add_argument('phase',choices=['d0','final']);p.add_argument('panel',choices=['one','two']);a=p.parse_args()
required=('own-final'if a.phase=='d0'else'grade-d0')if a.panel=='one'else'grade-'+a.phase+'-one'
receipt=ex.gate.authorize(R/'gates',required,R)
for task in ['T1','T2','T3']:
 out=R/'judgments'/a.phase/a.panel/task;inputs=R/'evaluation-inputs'/a.phase/task
 message=f'''You are an independent anonymous native UI acceptance reviewer, required by a preregistered blind comparison. You receive no arm assignments, original self-reviews, previous trial cases, other judge output or desired result. Read ONLY the approved public/private design sources referenced by your inputs, source capsules referenced there, original common-corpora paths referenced there, the frozen candidate-v8 generic evaluator documentation/scripts, and {inputs}. Do not read private/assignment.json, submissions outside the referenced source capsules, other judgments/evaluation, own-corpora, original reviews, tools-development or old studies. Write ONLY {out}. No production changes, SDK acquisitions, commits or messages to other agents.

Immediately record phase.json actual Unix/UTC start. Inspect source and ORIGINAL PNGs, actual state/input/action bindings, target boxes and coverage for BOTH anonymous sources, BOTH platforms and ALL cases delivered for task {task}, stage {a.phase}. Do not infer a pass from source or screenshot existence. You may create contact sheets labeled with original source/case/platform/state/index; retain originals and exact input hashes. The reference is independently approved design, not another candidate. Check every selected qualitative atom against its source-backed explicit proposition. Use null/unknown when original evidence or full-content coverage is insufficient. Inspect the whole state, including long content and caller updates, not only automatic F rows. Native/pixel numerical facts are recomputed by frozen tools and cannot be voted away; classify their CAUSE separately. Unsupported font/geometry fields remain U.

For each {inputs}/<source>/<platform>/<case> read inputs.json, plan.json, catalog.json, automatic.json and environment-check.json. The metadata gives original observation root, observation SHA, approved design/lock/policy/environment and actual source capsule. Write {out}/<source>/<platform>/<case>/judge.json exactly {{review:{{version:1,catalog_sha256:catalog.catalog_sha256,observation_sha256:inputs.observation_sha256,decisions:[{{review_id,actual:true|false|null,reason,snapshot_indices:[]}}]}},attributions:[{{id,cause,reason,snapshot_indices:[]}}]}}. Include all qualitative visual rows; do NOT submit pixel actuals, expected values, units, statuses or target overrides. Scope indices to exact coherent selected state via frozen native_checks.bound_state_evidence; null with empty indices is valid for missing state evidence. For every supported native/pixel or qualitative F, independently assess cause product/infrastructure/observation/uncertain with explicit rationale and original state indices. Strict F alone is not a product bug. Component canvas versus host ownership is fixed in the policy; source/raw native facts can establish whether an unexpected sampled region reflects a component defect or an unsuitable observation. Do not attribute an F whose exact selected state evidence is missing. Preserve contradictory evidence and uncertainty; do not choose a result to make an arm look better.

You may validate your own JSON with frozen acceptance.evaluate using your request twice ONLY as a schema self-check; that is not independent consensus. Never change a supported judgment merely to get a green report. Preserve rejected attempts in distinct files. Record input hashes, visual inspection coverage/limits, actual start/end times and commands. Finish by SEAL.json {{files:{{relative_path:SHA256}}}} for ALL output files except SEAL.json and __pycache__; no directory omissions. Do not edit anything after sealing. Report concise status with disagreement/uncertainty and actual coverage. All three members of this panel must seal before the next panel receives a prompt. AI agreement will be reported as consensus, not human gold.'''
 path=R/'prompts'/('judge-'+a.phase+'-'+a.panel+'-'+task+'.txt');path.parent.mkdir(exist_ok=True);path.write_text(message)
ex.save(R/'operators'/('judge-'+a.phase+'-'+a.panel+'-delivery.json'),{'atUnix':time.time(),'authorization':receipt,'promptHashes':{task:ex.sha(R/'prompts'/('judge-'+a.phase+'-'+a.panel+'-'+task+'.txt'))for task in ['T1','T2','T3']}})
print('Prepared independent panel delivery',a.phase,a.panel)
